function syncKeyPickups(){const pickups=doorLocks.getPickups(activeFloor),ids=new Set(pickups.map(p=>p.id));for(const entry of keyPickups)if(!ids.has(entry.id)){entry.mesh.removeFromParent();entry.mesh.geometry.dispose();entry.mesh.userData.disposeMaterials?.();}keyPickups=keyPickups.filter(p=>ids.has(p.id));for(const p of pickups){let entry=keyPickups.find(e=>e.id===p.id);if(!entry){const mesh=makeKeyPickup(THREE,p.kind!=='silver');mesh.userData.keyPickupId=p.id;world.add(mesh);entry={id:p.id,mesh};keyPickups.push(entry);}const [x,z]=coord(p.index);entry.mesh.position.set(x,groundHeight(x,z)+.75,z);entry.mesh.visible=!p.collected;}keyPickup=keyPickups.find(p=>p.id==='default:'+activeFloor)?.mesh??null;}
