function connectSession(session){if(!levels.length||isGenerating)throw Error('Wait for the dungeon to finish generating.');networkGame?.close();remoteInputs.clear();if(session.role==='host')for(const slot of session.connected){const hero=campaign.actor('hero-'+slot);remoteInputs.set(hero.id,{forward:0,strafe:0,yaw:hero.yaw,pitch:hero.pitch});}networkGame=createNetworkGame({session,getSnapshot:sessionSnapshot,onWorld:applyNetworkWorld,onState:applyNetworkState,onInput:(input,{actorId,disconnected})=>{if(disconnected){remoteInputs.delete(actorId);withHero(campaign.actor(actorId),()=>game.setGuard(false));}else{remoteInputs.set(actorId,input);const hero=campaign.actor(actorId);if(hero.offhand==='shield'&&hero.guarding!==input.blocking)withHero(hero,()=>game.setGuard(input.blocking));}},onAction:(kind,{actorId,targetId})=>['search-roll','search-close','take-item'].includes(kind)?remoteSearchAction(campaign.actor(actorId),kind,targetId):partyAction(campaign.actor(actorId),kind),onClass:(classId,{actorId})=>{if(campaign.state.phase!=='active'){campaign.setClass(actorId,classId);const hero=campaign.actor(actorId);hero.maxHealth=heroStats(hero).hp;if(hero.alive)hero.health=hero.maxHealth;}},onLoadout:(request,{actorId})=>{const hero=campaign.actor(actorId);if(request.slot)chooseLoadout(hero,request.slot,request.id);else{chooseLoadout(hero,'weapon',request.weapon);chooseLoadout(hero,'offhand',request.offhand);}},notify:toast});partyView.enabled=true;if(session.role==='guest'){document.body.classList.add('peer-guest');toast('Waiting for the host dungeon snapshot…');}else document.body.classList.remove('peer-guest');}
function makeContainerLoot(id){return [generateInventoryLoot({seed:(worldSeed+':'+id).slice(0,128)}),{id:'gold-'+random(id)().toString(36).slice(2),kind:'gold',amount:20+Math.floor(random(worldSeed+id)()*45)}];}
function openSearchContainer(config){config={...config,id:containerIdentity(worldSeed,config.id)};const hero=currentHero();if(hero.alive===false||hero.fainted||hero.escaped||partyView?.enabled&&campaign.state.phase!=='active')return false;const existing=containerCache.get(config.id);if(remoteSearches.has(hero.id)&&remoteSearches.get(hero.id).id!==config.id)return false;if([...remoteSearches.values()].some(r=>r.id===config.id&&r.owner?.id!==hero.id)||containerSearch.isOpen&&containerSearch.owner?.id!==hero.id)return false;const unlock=()=>withHero(hero,()=>config.onUnlock?.());if(networkGame?.role==='host'&&remoteInputs.has(hero.id)){let record=existing;if(!record){record={id:config.id,name:config.name??'Container',dc:config.dc??10,won:false,result:null,contents:null};containerCache.set(config.id,record);}if(record.status==='rolling')return false;record.owner=hero;record.onUnlock=unlock;record.status=record.won?'success':record.result?'failed':'ready';remoteSearches.set(hero.id,record);return true;}return containerSearch.show({...config,owner:hero,onUnlock:unlock});}
function remoteSearchAction(hero,kind,targetId){const record=remoteSearches.get(hero.id);if(!record)return false;if(kind==='search-close'){if(record.status==='rolling')return false;remoteSearches.delete(hero.id);return true;}if(!hero.alive||hero.fainted||hero.escaped||campaign.state.phase!=='active')return false;if(kind==='search-roll'){if(record.status==='rolling'||record.won)return false;const result=withHero(hero,()=>attemptHeroAction('search',{dc:record.dc,silent:true}));if(!result.allowed)return false;record.status='rolling';const rollToken=(record.rollToken??0)+1;record.rollToken=rollToken;const seed=worldSeed,run=campaign.runNumber;setTimeout(()=>{if(seed!==worldSeed||run!==campaign.runNumber||remoteSearches.get(hero.id)!==record||record.rollToken!==rollToken)return;record.result={...result,success:result.success&&hero.alive&&!hero.escaped&&campaign.state.phase==='active'};record.won=record.result.success;record.status=record.won?'success':'failed';if(record.won){record.contents??=makeContainerLoot(record.id);record.onUnlock?.();}},1100);return true;}if(kind==='take-item'&&record.won){const item=record.contents.find(i=>i.id===targetId);if(!item)return false;return withHero(hero,()=>{const accepted=item.kind==='gold'?(game.reward(item.amount),true):inventory.grantLoot(item);if(accepted)record.contents.splice(record.contents.indexOf(item),1);return accepted;});}return false;}
function currentHero(){if(actionActor)return actionActor;if(networkGame?.role==='guest'&&networkGame.actorId)return campaign.actor(networkGame.actorId);return actionActor??(partyView?.enabled?(partyView.focusedActor??campaign.actors[0]):actions.actor);}
function heroWeaponId(hero){const previous=inventoryActor;inventoryActor=hero;try{return inventory.getEquipped('weapon')?.id??'starter:'+(hero.classId??'adventurer');}finally{inventoryActor=previous;}}
